import pytest
from llm_runtime.token_counter import count_tokens

def test_empty_string():
    assert count_tokens('') == 0

def test_ascii():
    assert count_tokens('hello world') == 2

def test_unicode():
    assert count_tokens('你好世界') == 4

def test_long_text():
    assert count_tokens('a ' * 1000) >= 1000

import pytest
from llm_runtime.observation_compressor import compress

def test_noop_short():
    assert compress('hi') == 'hi'

def test_truncate_long():
    out = compress('x' * 10000, max_chars=128)
    assert len(out) <= 128

def test_preserve_head_tail():
    out = compress('A' * 100 + 'MIDDLE' + 'B' * 100, max_chars=64)
    assert out.startswith('A') and out.endswith('B')

import pytest
from react_style_coding_agent import loop_engineering_static

@pytest.mark.parametrize('seed', [1, 2, 3])
def test_loop_terminates(seed):
    assert loop_engineering_static(seed=seed, max_rounds=5) is not None

def test_loop_respects_max_rounds():
    out = loop_engineering_static(seed=0, max_rounds=2)
    assert out['rounds'] <= 2

# Implements README §压缩策略: step-level S by default, trajectory-level mix at trigger_point.

from dataclasses import dataclass

def at_trigger_point(state) -> bool:
    return state.tokens_until_compression < state.trigger_threshold

def mix_trajectory(step_summary: str, ctx_state: dict) -> str:
    if not at_trigger_point(ctx_state):
        return step_summary
    traj_line = f"[traj] {ctx_state['traj_digest']}"
    return f"{step_summary}\n{traj_line}"
